<template>
  <BioNexusDialog ref="dialog" size="wide" dialog-class="routine-entry-dialog" shell-class="routine-entry-shell" body-class="routine-entry-body" :prevent-close="saving" :kicker="mode === 'create' ? 'Nuevo registro' : 'Editar registro'" :title="mode === 'create' ? 'Crear rutina' : 'Editar rutina'" @close="handleClosed">
