const props=defineProps({saving:Boolean,canCreate:Boolean,canUpdate:Boolean,exams:{type:Array,default:()=>[]}});const emit=defineEmits(["submit"]);const dialog=ref(null),detailDialog=ref(null),firstInput=ref(null),mode=ref("create"),current=ref(null),search=ref(""),attempted=ref(false),errorMessage=ref(""),original=ref(""),dirty=ref(false),initializing=ref(false),dragId=ref(null),keyboardId=ref(null),keyboardOriginal=ref([]);const draft=reactive({description:"",details:"",exams:[]});
const values=computed(()=>({description:draft.description.trim(),details:draft.details.trim(),registered_exams:draft.exams.map(item=>{const row={examId:item.examId};if(Object.prototype.hasOwnProperty.call(item,"active"))row.active=Boolean(item.active);return row})}));const signature=computed(()=>JSON.stringify(values.value));const descriptionError=computed(()=>attempted.value&&!values.value.description?"La descripción es obligatoria.":"");const submitDisabled=computed(()=>initializing.value||props.saving||!dirty.value||(mode.value==="create"?!props.canCreate:!props.canUpdate));const available=computed(()=>{const query=search.value.trim().toLowerCase(),used=new Set(draft.exams.map(item=>item.examId));return props.exams.filter(exam=>!exam.annulled&&!used.has(exam.id)&&(!query||`${exam.description} ${exam.abbreviation}`.toLowerCase().includes(query)))});
function assign(row){draft.description=row?.description||"";draft.details=row?.details||"";draft.exams=(row?.registered_exams||[]).map(item=>({...item,description:item.description||props.exams.find(exam=>exam.id===item.examId)?.description||`Examen ${item.examId}`}))}function snapshot(){return JSON.stringify(values.value)}function syncDirty(){dirty.value=!initializing.value&&snapshot()!==original.value}async function show(){await dialog.value?.open();await nextTick();original.value=snapshot();dirty.value=false;initializing.value=false;firstInput.value?.focus()}async function openCreate(){initializing.value=true;mode.value="create";current.value=null;assign(null);attempted.value=false;errorMessage.value="";search.value="";await show()}async function openEdit(row){initializing.value=true;mode.value="edit";current.value=row;assign(row);attempted.value=false;errorMessage.value="";search.value="";await show()}function openDetail(exam){detailDialog.value?.open(exam)}async function add(exam){draft.exams.push({examId:exam.id,description:exam.description,abbreviation:exam.abbreviation});await nextTick();syncDirty();keyboardId.value=null;selectKeyboard(exam.id);focusRow(exam.id,{block:"end"})}function remove(index){draft.exams.splice(index,1);syncDirty();keyboardId.value=null}function move(index,delta){const target=index+delta;if(target<0||target>=draft.exams.length)return;const[row]=draft.exams.splice(index,1);draft.exams.splice(target,0,row);syncDirty();focusRow(row.examId)}function selectKeyboard(id){if(keyboardId.value!==id){keyboardId.value=id;keyboardOriginal.value=draft.exams.map(item=>item.examId)}}function activateKeyboardSelection(id,event){event?.preventDefault?.();event?.stopPropagation?.();if(keyboardId.value===id)return;keyboardId.value=null;selectKeyboard(id);focusRow(id)}function focusRow(id,options={}){nextTick(()=>{const row=document.querySelector(`[data-routine-key="${id}"]`);row?.focus({preventScroll:true});row?.scrollIntoView({block:options.block||"neares