ue=null}function setError(value){errorMessage.value=String(value||"")}function clearError(){errorMessage.value=""}globalThis.addEventListener("keydown",handleKey,{capture:true});onBeforeUnmount(()=>globalThis.removeEventListener("keydown",handleKey,{capture:true}));defineExpose({openCreate,openEdit,close,setError,clearError});
